class Solution {
    public boolean wordPattern(String pattern, String s) {
        Map<Character, String> ch2str = new HashMap<>();
        Map<String, Character> str2ch = new HashMap<>();
        String[] ss = s.split(" ");
        int n = pattern.length();
        if (n != ss.length) {
            return false;
        }
        for (int i = 0; i < n; ++i) {
            char ch = pattern.charAt(i);
            if (ch2str.containsKey(ch) && !ch2str.get(ch).equals(ss[i])) {
                return false;
            }
            if (str2ch.containsKey(ss[i]) && !str2ch.get(ss[i]).equals(ch)) {
                return false;
            }
            ch2str.put(ch, ss[i]);
            str2ch.put(ss[i], ch);
        }
        return true;
    }
}

class Solution {
public:
    bool wordPattern(string pattern, string s) {
        stringstream ss(s);
        unordered_map<char, string> m;
        string word;
        int i=0;
        unordered_map<char, int> cCount;
        unordered_map<string, int> sCount;

        while(ss >> word){
            if(i+1 > pattern.size())
                return false;

            if(m[pattern[i]].size() != 0)
                if(m[pattern[i]] != word)
                    return false;

            if(cCount[pattern[i]] != sCount[word])
                return false;

            m[pattern[i]]=word;
            cCount[pattern[i]]++;
            sCount[word]++;
            i++;
        }

        if(i != pattern.size())
                return false;

        return true;
    }
};

