class Solution {
public:
    bool wordPattern(string pattern, string s) {
        unordered_map<char,int> ump1;
        unordered_map<string,int> ump2;
        stringstream str(s);
        string temp;
        int i=0,n=pattern.size();
        for(;str>>temp;i++)
        {
            if(i==n or ump1[pattern[i]]!=ump2[temp])
                return false;
            ump1[pattern[i]]=i+1;
            ump2[temp]=i+1;
        }
        return i==n;
    }
};

class Solution(object):
    def wordPattern(self, pattern, str):
        """
        :type pattern: str
        :type str: str
        :rtype: bool
        """
        words = str.split()
        if len(words) != len(pattern):
            return False
        d = {}
        for i,c in enumerate(pattern):
            if c not in d:
                d[c] = words[i]
            else:
                if d[c]!= words[i]:
                    return False
        values = set()
        for k in d:
            if d[k] in values:
                return False
            values.add(d[k])
        return True

